(92, 'dragao-de-bronze-jovem', 'Dragão de Bronze Jovem', 8, 142, 18, '{"index":"dragao-de-bronze-jovem","name":"Dragão de Bronze Jovem","size":"Grande","type":"dragão","subtype":null,"swarm_of":null,"alignment":"leal e bom","armor_class":[{"value":18,"desc":"armadura natural"}],"hit_points":142,"hit_dice":"15d10","hit_points_roll":"15d10+60","speed":{"terrestre":"12 m","natação":"12 m","voo":"24 m"},"strength":21,"dexterity":10,"constitution":19,"intelligence":14,"wisdom":13,"charisma":17,"saving_throws":[{"ability":"DES","bonus":3},{"ability":"CON","bonus":7},{"ability":"SAB","bonus":4},{"ability":"CAR","bonus":6}],"skills":[{"name":"Furtividade","bonus":3},{"name":"Intuição","bonus":4},{"name":"Percepção","bonus":7}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["elétrico"],"condition_immunities":[],"senses":"percepção às cegas 9 m, visão no escuro 36 m, Percepção passiva 17","passive_perception":17,"languages":"Comum, Dracônico","challenge_rating":8,"xp":3900,"proficiency_bonus":3,"special_abilities":[{"name":"Anfíbio","desc":"O dragão pode respirar ar e água.","usage":null,"attack":null,"damage":[],"dc":null,"multiattack":null}],"actions":[{"name":"Ataques Múltiplos","desc":"O dragão realiza três ataques: um com sua mordida e dois com suas garras.","usage":null,"attack":null,"damage":[],"dc":null,"multiattack":[{"action":"Mordida","count":1},{"action":"Garra","count":2}]},{"name":"Mordida","desc":"Ataque Corpo-a-Corpo com Arma: +8 para atingir, alcance 3 m, um alvo. Acerto: 16 (2d10 + 5) de dano perfurante.","usage":null,"attack":{"kind":"melee_weapon","bonus":8,"reach_m":3,"range_m":null,"target":"um alvo"},"damage":[{"dice":"2d10+5","average":16,"type":"perfurante"}],"dc":null,"multiattack":null},{"name":"Garra","desc":"Ataque Corpo-a-Corpo com Arma: +8 para atingir, alcance 1,5 m, um alvo. Acerto: 12 (2d6 + 5) de dano cortante.","usage":null,"attack":{"kind":"melee_weapon","bonus":8,"reach_m":1.5,"range_m":null,"target":"um alvo"},"