(273, 'serpente-de-fogo', 'Serpente de Fogo', 1, 22, 14, '{"index":"serpente-de-fogo","name":"Serpente de Fogo","size":"Médio","type":"elemental","subtype":null,"swarm_of":null,"alignment":"neutro e mau","armor_class":[{"value":14,"desc":"armadura natural"}],"hit_points":22,"hit_dice":"5d8","hit_points_roll":"5d8","speed":{"terrestre":"9 m"},"strength":12,"dexterity":14,"constitution":11,"intelligence":7,"wisdom":10,"charisma":8,"saving_throws":[],"skills":[],"damage_vulnerabilities":["frio"],"damage_resistances":["concussão, cortante e perfurante de ataques não-mágicos"],"damage_immunities":["fogo"],"condition_immunities":[],"senses":"visão no escuro 18 m, Percepção passiva 10","passive_perception":10,"languages":"compreende Ignan, mas não pode falar","challenge_rating":1,"xp":200,"proficiency_bonus":2,"special_abilities":[{"name":"Corpo Ardente","desc":"Uma criatura que toque a serpente ou atinja ela com um ataque corpo-a-corpo a 1,5 metro dela sofre 3 (1d6) de dano de fogo.","usage":null,"attack":null,"damage":[{"dice":"1d6","average":3,"type":"fogo"}],"dc":null,"multiattack":null}],"actions":[{"name":"Ataques Múltiplos","desc":"A serpente realiza dois ataques: um com sua mordida e um com sua cauda.","usage":null,"attack":null,"damage":[],"dc":null,"multiattack":[{"action":"Mordida","count":1},{"action":"Cauda","count":1}]},{"name":"Mordida","desc":"Ataque Corpo-a-Corpo com Arma: +3 para atingir, alcance 1,5 m, um alvo. Acerto: 3 (1d4 + 1) de dano perfurante mais 3 (1d6) de dano de fogo.","usage":null,"attack":{"kind":"melee_weapon","bonus":3,"reach_m":1.5,"range_m":null,"target":"um alvo"},"damage":[{"dice":"1d4+1","average":3,"type":"perfurante"},{"dice":"1d6","average":3,"type":"fogo"}],"dc":null,"multiattack":null},{"name":"Cauda","desc":"Ataque Corpo-a-Corpo com Arma: +3 para atingir, alcance 1,5 m, um alvo. Acerto: 3 (1d4 + 1) de dano de concussão mais 3 (1d6) de dano de fogo.","usage":null,"attack":{"kind":"melee_weapon","bonus":3,"reach_m":1.5,"range_m":n