(321, 'aranha-interplanar', 'Aranha Interplanar', 3, 32, 13, '{"index":"aranha-interplanar","name":"Aranha Interplanar","size":"Grande","type":"monstruosidade","subtype":null,"swarm_of":null,"alignment":"imparcial","armor_class":[{"value":13,"desc":"armadura natural"}],"hit_points":32,"hit_dice":"5d10","hit_points_roll":"5d10+5","speed":{"terrestre":"9 m","escalada":"9 m"},"strength":15,"dexterity":15,"constitution":12,"intelligence":6,"wisdom":10,"charisma":6,"saving_throws":[],"skills":[{"name":"Furtividade","bonus":6}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":"visão no escuro 18 m, Percepção passiva 10","passive_perception":10,"languages":"","challenge_rating":3,"xp":700,"proficiency_bonus":2,"special_abilities":[{"name":"Escalada Aracnídea","desc":"A aranha pode escalar superfícies difíceis, incluindo tetos de cabeça para baixo, sem precisar realizar um teste de habilidade.","usage":null,"attack":null,"damage":[],"dc":null,"multiattack":null},{"name":"Salto Etéreo","desc":"Com uma ação bônus, a aranha pode, magicamente, mudar do Plano Material para o Plano Etéreo, ou vice-versa.","usage":null,"attack":null,"damage":[],"dc":null,"multiattack":null},{"name":"Andar na Teia","desc":"A aranha ignora restrições de movimento causadas por estar numa teia.","usage":null,"attack":null,"damage":[],"dc":null,"multiattack":null}],"actions":[{"name":"Mordida","desc":"Ataque Corpo-a-Corpo com Arma: +4 para atingir, alcance 1,5 m, uma criatura. Acerto: 7 (1d10 + 2) de dano perfurante e o alvo deve realizar um teste de resistência de Constituição CD 11, sofrendo 18 (4d8) de dano de veneno se falhar na resistência ou metade desse dano se obtiver sucesso. Se o dano de veneno reduzir o alvo a 0 pontos de vida, o alvo estará estável, porém, envenenado, por 1 hora e paralisado enquanto estiver envenenado dessa forma.","usage":null,"attack":{"kind":"melee_weapon","bonus":4,"reach_m":1.5,"range_m":null,"target":"uma c