(421, 'gladiador', 'Gladiador', 5, 112, 16, '{"index":"gladiador","name":"Gladiador","size":"Médio","type":"humanoide","subtype":"qualquer raça","swarm_of":null,"alignment":"qualquer tendência","armor_class":[{"value":16,"desc":"couro batido, escudo"}],"hit_points":112,"hit_dice":"15d8","hit_points_roll":"15d8+45","speed":{"terrestre":"9 m"},"strength":18,"dexterity":15,"constitution":16,"intelligence":10,"wisdom":12,"charisma":15,"saving_throws":[{"ability":"FOR","bonus":7},{"ability":"DES","bonus":5},{"ability":"CON","bonus":6}],"skills":[{"name":"Atletismo","bonus":10},{"name":"Intimidação","bonus":5}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":"Percepção passiva 11","passive_perception":11,"languages":"um idioma qualquer (geralmente Comum)","challenge_rating":5,"xp":1800,"proficiency_bonus":3,"special_abilities":[{"name":"Bravura","desc":"O gladiador tem vantagem em testes de resistência para não ser amedrontado.","usage":null,"attack":null,"damage":[],"dc":null,"multiattack":null},{"name":"Brutamontes","desc":"Um ataque corpo-a-corpo com arma causa um dado extra de dano quando o gladiador atinge com ele (incluso no ataque).","usage":null,"attack":null,"damage":[],"dc":null,"multiattack":null}],"actions":[{"name":"Ataques Múltiplos","desc":"O gladiador realiza três ataques corpo-a-corpo ou dois ataques à distância.","usage":null,"attack":null,"damage":[],"dc":null,"multiattack":[{"action":"Lança","count":3}]},{"name":"Lança","desc":"Ataque Corpo-a-Corpo ou à Distância com Arma: +7 para atingir, alcance 1,5 m e distância 6/18 m, um alvo. Acerto: 11 (2d6 + 4) de dano perfurante, ou 13 (2d8 + 4) de dano perfurante se for usada com as duas mãos para realizar ataques corpo-a-corpo.","usage":null,"attack":{"kind":"melee_or_ranged_weapon","bonus":7,"reach_m":1.5,"range_m":"6/18","target":"um alvo"},"damage":[{"dice":"2d6+4","average":11,"type":"perfurante"},{"dice":"2d8+4","average":13,"type":"perfurant